  &
   \color{lightgray}{
    \rightarrow
       \int_\mathcal{V} u \frac{\partial \phi}{\partial x}  \, d\mathcal{V}
    \rightarrow
       \int_\mathcal{S} u \phi \, d\mathcal{S}
    \rightarrow
      -  \left[ u \phi \right]_{k}
      +  \left[ u \phi \right]_{k+1}  
  }
  \\
  &
   \color{lightgray}{
    \rightarrow
      - u \frac{\phi_{m-1} + \phi_{m}}{2}
      + u \frac{\phi_m + \phi_{m+1}}{2}
    \rightarrow
    u \frac{{\phi}_{m+1}-{\phi}_{m-1}}{2}
  }
  \\
\Gamma  \frac{\partial }{\partial x}   \frac{\partial \phi}{\partial x}
  &
   \color{lightgray}{
    \rightarrow
       \int_\mathcal{V} \Gamma  \frac{\partial }{\partial x}  \frac{\partial \phi}{\partial x}  \, d\mathcal{V}
    \rightarrow
       \int_\mathcal{S} \Gamma  \frac{\partial \phi}{\partial x}  \, d\mathcal{S}
    \rightarrow
      -  \left[ \Gamma \frac{\partial  \phi}{\partial x}  \right]_{k}
      +  \left[ \Gamma  \frac{\partial \phi}{\partial x}  \right]_{k+1}  
  }
  \\
